```

```kotlin
// Location: outbound/repository/cache/src/main/kotlin/.../ValkeyL2CacheProvider.kt
package com.cowave.search.repository.cache

import com.cowave.shared.cache.L2CacheProvider
import com.cowave.shared.utils.logger
import org.springframework.data.redis.core.RedisTemplate
import org.springframework.stereotype.Component
import java.util.concurrent.TimeUnit

@Component
class ValkeyL2CacheProvider(
    private val redisTemplate: RedisTemplate<String, String>,
) : L2CacheProvider {

    companion object {
        private val log by logger()
        private const val KEY_PREFIX = "tiered-cache"
    }

    override fun get(cacheName: String, key: String): String? =
        runCatching {
            val fullKey = buildKey(cacheName, key)
            redisTemplate.opsForValue().get(fullKey)
        }.onFailure { e ->
            log.error("L2 cache GET failed [{}:{}]", cacheName, key, e)
        }.getOrNull()  // graceful degradation: return null on failure

    override fun put(cacheName: String, key: String, value: String, ttlSeconds: Long) {
        runCatching {
            val fullKey = buildKey(cacheName, key)
            redisTemplate.opsForValue().set(fullKey, value, ttlSeconds, TimeUnit.SECONDS)
        }.onFailure { e ->
            log.error("L2 cache PUT failed [{}:{}]", cacheName, key, e)
        }
    }

    override fun evict(cacheName: String, key: String) {
        runCatching {
            redisTemplate.delete(buildKey(cacheName, key))
        }.onFailure { e ->
            log.error("L2 cache EVICT failed [{}:{}]", cacheName, key, e)
        }
    }

    override fun evictAll(cacheName: String) {
        runCatching {
            val pattern = "$KEY_PREFIX:$cacheName:*"
            val keys = redisTemplate.keys(pattern)
            if (keys.isNotEmpty()) {
                redisTemplate.delete(keys)
            }
        }.onFailure { e ->
            log.error("L2 cache EVICT_ALL failed [{}]", cacheName, e)
        }
    }

    private fun buildKey(cacheName: String, key: String): String =
        "$KEY_PREFIX:$cacheName:$key"
}
```

### 3.5 Serialization Strategy

```kotlin
// Location: shared/src/main/kotlin/com/cowave/shared/cache/CacheSerializer.kt
package com.cowave.shared.cache

import com.fasterxml.jackson.databind.ObjectMapper
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule
import com.fasterxml.jackson.module.kotlin.jacksonObjectMapper
import com.fasterxml.jackson.module.kotlin.readValue

object CacheSerializer {
    private val objectMapper: ObjectMapper = jacksonObjectMapper().apply {
        registerModule(JavaTimeModule())
        // Do NOT fail on unknown properties for forward compatibility
        configure(
            com.fasterxml.jackson.databind.DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES,
            false
        )
    }

    fun serialize(value: Any): String = objectMapper.writeValueAsString(value)

    fun <T> deserialize(json: String, type: Class<T>): T = objectMapper.readValue(json, type)

    /**
     * For generic types like List<Brand>, use TypeReference.
     */
    fun <T> deserialize(json: String, typeRef: com.fasterxml.jackson.core.type.TypeReference<T>): T =
        objectMapper.readValue(json, typeRef)

    /**
     * Deserialize with runtime type token (captures generic return type from Method).
     */
    fun deserializeByJavaType(json: String, javaType: com.fasterxml.jackson.databind.JavaType): Any =
        objectMapper.readValue(json, javaType)
}
```

### 3.6 Cache Key Generator

```kotlin
// Location: shared/src/main/kotlin/com/cowave/shared/cache/CacheKeyGenerator.kt
package com.cowave.shared.cache

import org.aspectj.lang.ProceedingJoinPoint
import org.aspectj.lang.reflect.MethodSignature
import org.springframework.context.expression.MethodBasedEvaluationContext
import org.springframework.core.DefaultParameterNameDiscoverer
import org.springframework.expression.spel.standard.SpelExpressionParser

object CacheKeyGenerator {
    private val parser = SpelExpressionParser()
    private val parameterNameDiscoverer = DefaultParameterNameDiscoverer()

    /**
     * Generate a cache key from SpEL expression.
     * If key expression is empty, generate from all method arguments.
     */
    fun generateKey(joinPoint: ProceedingJoinPoint, keyExpression: String): String {
        if (keyExpression.isBlank()) {
            return generateDefaultKey(joinPoint)
        }
        return evaluateSpel(joinPoint, keyExpression)
    }

    /**
     * Evaluate a SpEL condition expression. Returns true if blank (no condition).
     */
    fun evaluateCondition(
        joinPoint: ProceedingJoinPoint,
        conditionExpression: String,
        result: Any? = null,
    ): Boolean {
        if (conditionExpression.isBlank()) return true
        val value = evaluateSpelWithResult(joinPoint, conditionExpression, result)
        return value as? Boolean ?: true
    }

    private fun generateDefaultKey(joinPoint: ProceedingJoinPoint): String {
        val args = joinPoint.args
        if (args.isNullOrEmpty()) return "NO_ARGS"

        return args.joinToString(":") { arg ->
            when (arg) {
                null -> "null"
                is Collection<*> -> arg.sortedBy { it.toString() }.joinToString(",")
                is Array<*> -> arg.sortedBy { it.toString() }.joinToString(",")
                else -> arg.toString()
            }
        }
    }

    private fun evaluateSpel(joinPoint: ProceedingJoinPoint, expression: String): String {
        val signature = joinPoint.signature as MethodSignature
        val method = signature.method
        val context = MethodBasedEvaluationContext(
            joinPoint.target,
            method,
            joinPoint.args,
            parameterNameDiscoverer,
        )
        val parsed = parser.parseExpression(expression)
        return parsed.getValue(context)?.toString() ?: "null"
    }

    private fun evaluateSpelWithResult(
        joinPoint: ProceedingJoinPoint,
        expression: String,
        result: Any?,
    ): Any? {
        val signature = joinPoint.signature as MethodSignature
        val method = signature.method
        val context = MethodBasedEvaluationContext(
            joinPoint.target,
            method,
            joinPoint.args,
            parameterNameDiscoverer,
        )
        if (result != null) {
            context.setVariable("result", result)
        }
        val parsed = parser.parseExpression(expression)
        return parsed.getValue(context)
    }
}
