### 3.7 AOP Aspect: `TieredCacheAspect`

```kotlin
// Location: shared/src/main/kotlin/com/cowave/shared/cache/TieredCacheAspect.kt
package com.cowave.shared.cache

import com.cowave.shared.utils.logger
import com.fasterxml.jackson.databind.ObjectMapper
import com.fasterxml.jackson.module.kotlin.jacksonObjectMapper
import org.aspectj.lang.ProceedingJoinPoint
import org.aspectj.lang.annotation.Around
import org.aspectj.lang.annotation.Aspect
import org.aspectj.lang.reflect.MethodSignature
import org.springframework.stereotype.Component

@Aspect
@Component
class TieredCacheAspect(
    private val l1CacheProvider: L1CacheProvider,
    private val l2CacheProvider: L2CacheProvider?,  // nullable for L1-only deployments
) {
    companion object {
        private val log by logger()
        private val objectMapper: ObjectMapper = jacksonObjectMapper().apply {
            registerModule(com.fasterxml.jackson.datatype.jsr310.JavaTimeModule())
        }
    }

    @Around("@annotation(tieredCache)")
    fun around(joinPoint: ProceedingJoinPoint, tieredCache: TieredCache): Any? {
        // 1. Evaluate condition
        if (!CacheKeyGenerator.evaluateCondition(joinPoint, tieredCache.condition)) {
            log.debug("Cache condition not met, executing method directly")
            return joinPoint.proceed()
        }

        val cacheName = tieredCache.cacheName
        val cacheKey = CacheKeyGenerator.generateKey(joinPoint, tieredCache.key)
        val returnType = resolveReturnJavaType(joinPoint)

        // 2. Check L1
        val l1Result = l1CacheProvider.get(cacheName, cacheKey, Any::class.java)
        if (l1Result != null) {
            log.debug("L1 HIT [{}:{}]", cacheName, cacheKey)
            return l1Result
        }
        log.debug("L1 MISS [{}:{}]", cacheName, cacheKey)

        // 3. Check L2 (if enabled and provider available)
        if (tieredCache.l2Enabled && l2CacheProvider != null) {
            val l2Json = l2CacheProvider.get(cacheName, cacheKey)
            if (l2Json != null) {
                log.debug("L2 HIT [{}:{}]", cacheName, cacheKey)
                val deserialized = CacheSerializer.deserializeByJavaType(l2Json, returnType)
                // Populate L1
                l1CacheProvider.put(
                    cacheName, cacheKey, deserialized,
                    tieredCache.l1TtlSeconds, tieredCache.l1MaxSize,
                )
                return deserialized
            }
            log.debug("L2 MISS [{}:{}]", cacheName, cacheKey)
        }

        // 4. Execute actual method
        val result = joinPoint.proceed()

        // 5. Evaluate 'unless' condition
        if (result != null && !CacheKeyGenerator.evaluateCondition(
                joinPoint, tieredCache.unless, result
            ).let { !it || tieredCache.unless.isBlank() }
        ) {
            // 'unless' evaluated to true, skip caching
            log.debug("Cache 'unless' condition met, skipping cache population")
            return result
        }

        // 6. Populate caches
        if (result != null) {
            // Populate L1
            l1CacheProvider.put(
                cacheName, cacheKey, result,
                tieredCache.l1TtlSeconds, tieredCache.l1MaxSize,
            )

            // Populate L2
            if (tieredCache.l2Enabled && l2CacheProvider != null) {
                val json = CacheSerializer.serialize(result)
                l2CacheProvider.put(cacheName, cacheKey, json, tieredCache.l2TtlSeconds)
            }
        }

        return result
    }

    @Around("@annotation(evict)")
    fun aroundEvict(joinPoint: ProceedingJoinPoint, evict: TieredCacheEvict): Any? {
        val result = joinPoint.proceed()

        if (evict.allEntries) {
            l1CacheProvider.evictAll(evict.cacheName)
            l2CacheProvider?.evictAll(evict.cacheName)
        } else {
            val key = CacheKeyGenerator.generateKey(joinPoint, evict.key)
            l1CacheProvider.evict(evict.cacheName, key)
            l2CacheProvider?.evict(evict.cacheName, key)
        }

        return result
    }

    private fun resolveReturnJavaType(joinPoint: ProceedingJoinPoint):
        com.fasterxml.jackson.databind.JavaType {
        val method = (joinPoint.signature as MethodSignature).method
        val javaType = objectMapper.typeFactory.constructType(method.genericReturnType)
        return javaType
    }
}
